    /// <summary>
    /// Utility class for converting between Unity Texture2D and ICO (.ico) file format.
    /// <para>
    /// ICO files can contain multiple images at different sizes. All images are stored
    /// as 32-bit BGRA (uncompressed BMP DIB) data. PNG-embedded ICO is not produced
    /// on output, but PNG-embedded entries encountered on input are decoded correctly.
    /// </para>
    /// Supported sizes on output: any power-of-two or standard icon size (16, 32, 48, 64, 128, 256).
    /// The texture must be readable (Read/Write enabled in import settings).
    /// </summary>
    public static class ICOConvert
    {
        // ICO/CUR reserved type identifiers
        private const ushort ICO_RESERVED = 0;
        private const ushort ICO_TYPE = 1; // .ico

        // BITMAPINFOHEADER size (always 40 for ICO DIB entries)
        private const int BMIH_SIZE = 40;

        // PNG magic bytes for detecting PNG-embedded ICO entries
        private static readonly byte[] PNG_MAGIC = { 0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A };

        #region Texture2D to ICO

        /// <summary>
        /// Converts a single Texture2D into ICO bytes containing one image at the texture's
        /// original size. The texture must be readable and will be sampled as RGBA32.
        /// </summary>
        /// <param name="texture">Source texture. Must have Read/Write enabled.</param>
        /// <returns>Raw bytes of a valid .ico file.</returns>
        public static byte[] TextureToICOBytes(this Texture2D texture)
        {
            if (texture == null)
                throw new ArgumentNullException(nameof(texture));

            return TexturesToICOBytes(new[] { texture });
        }

        /// <summary>
        /// Converts one or more Texture2Ds into a single ICO file containing one image entry
        /// per texture. This is useful for providing multiple resolutions (e.g. 16, 32, 48, 256)
        /// inside a single .ico file. Each texture must be readable.
        /// </summary>
        /// <param name="textures">
        /// Array of source textures. Typical ICO sets: 16×16, 32×32, 48×48, 256×256.
        /// </param>
        /// <returns>Raw bytes of a valid .ico file.</returns>
        public static byte[] TexturesToICOBytes(Texture2D[] textures)
        {
            if (textures == null || textures.Length == 0)
                throw new ArgumentException("At least one texture is required.", nameof(textures));
            if (textures.Length > 255)
                throw new ArgumentException("ICO files support a maximum of 255 images.", nameof(textures));

            // Pre-encode each texture into a DIB (BMP pixel block) so we know exact sizes
            var dibBlocks = new byte[textures.Length][];
            for (int i = 0; i < textures.Length; i++)
            {
                if (textures[i] == null)
                    throw new ArgumentNullException($"textures[{i}]", "Texture entry must not be null.");
                dibBlocks[i] = EncodeDIB(textures[i]);
            }

            using var ms = new MemoryStream();
            using var writer = new BinaryWriter(ms);

            // ---- ICONDIR header (6 bytes) ----
            writer.Write(ICO_RESERVED); // idReserved — must be 0
            writer.Write(ICO_TYPE);     // idType    — 1 = ICO
            writer.Write((ushort)textures.Length); // idCount

            // Directory entries start at byte 6; each entry is 16 bytes
            int dirOffset = 6;
            int entryStride = 16;
            int dataOffset = dirOffset + entryStride * textures.Length;

            // ---- ICONDIRENTRY array ----
            for (int i = 0; i < textures.Length; i++)
            {
                int w = textures[i].width;
                int h = textures[i].height;

                // ICO stores 0 for 256 (field is a single byte, max 255)
                writer.Write((byte)(w >= 256 ? 0 : w));
                writer.Write((byte)(h >= 256 ? 0 : h));
                writer.Write((byte)0);   // wColorCount — 0 for 32-bpp (true color)
                writer.Write((byte)0);   // wReserved
                writer.Write((ushort)1); // wPlanes
                writer.Write((ushort)32);// wBitCount  — 32-bit BGRA
                writer.Write((uint)dibBlocks[i].Length); // dwBytesInRes
                writer.Write((uint)dataOffset);           // dwImageOffset

                dataOffset += dibBlocks[i].Length;
            }

            // ---- Image data ----
            foreach (byte[] dib in dibBlocks)
                writer.Write(dib);

            return ms.ToArray();
        }

        /// <summary>
        /// Converts a Texture2D to a .ico file and saves it to disk.
        /// </summary>
        /// <param name="texture">Source texture. Must have Read/Write enabled.</param>
        /// <param name="outputPath">Full path including filename, e.g. "C:/icons/app.ico".</param>
        public static void TextureToICOFile(this Texture2D texture, string outputPath)
        {
            if (string.IsNullOrEmpty(outputPath))
                throw new ArgumentException("Output path must not be null or empty.", nameof(outputPath));

            File.WriteAllBytes(outputPath, TextureToICOBytes(texture));
        }

        /// <summary>
        /// Converts multiple Texture2Ds to a multi-resolution .ico file and saves it to disk.
        /// </summary>
        /// <param name="textures">Array of source textures (one per desired icon resolution).</param>
        /// <param name="outputPath">Full path including filename, e.g. "C:/icons/app.ico".</param>
        public static void TexturesToICOFile(Texture2D[] textures, string outputPath)
        {
            if (string.IsNullOrEmpty(outputPath))
                throw new ArgumentException("Output path must not be null or empty.", nameof(outputPath));

            File.WriteAllBytes(outputPath, TexturesToICOBytes(textures));
        }

        #endregion

        #region ICO to Texture2D

        /// <summary>
        /// Converts ICO bytes into an array of Texture2Ds — one per image entry in the file.
        /// Supports both uncompressed 32-bit DIB entries and PNG-embedded entries.
        /// </summary>
        /// <param name="icoBytes">Raw bytes of a .ico file.</param>
        /// <param name="filterMode">Filter mode applied to each resulting texture.</param>
        /// <param name="wrapMode">Wrap mode applied to each resulting texture.</param>
        /// <returns>
        /// An array of Texture2D objects in the order they appear in the ICO directory.
        /// </returns>
        public static Texture2D[] ICOBytesToTextures(
            byte[] icoBytes,
            FilterMode filterMode = FilterMode.Bilinear,
            TextureWrapMode wrapMode = TextureWrapMode.Clamp)
        {
            if (icoBytes == null || icoBytes.Length < 6)
                throw new ArgumentException("Invalid or too-short ICO byte array.", nameof(icoBytes));

            using var reader = new BinaryReader(new MemoryStream(icoBytes));

            // ---- ICONDIR ----
            ushort reserved = reader.ReadUInt16();
            ushort type = reader.ReadUInt16();
            ushort count = reader.ReadUInt16();

            if (reserved != 0 || type != ICO_TYPE)
                throw new InvalidDataException(
                    $"Not a valid ICO file. reserved={reserved}, type={type}");
            if (count == 0)
                throw new InvalidDataException("ICO file contains no image entries.");

            // ---- ICONDIRENTRY array ----
            var entries = new ICODirEntry[count];
            for (int i = 0; i < count; i++)
            {
                entries[i] = new ICODirEntry
                {
                    Width = reader.ReadByte(),
                    Height = reader.ReadByte(),
                    ColorCount = reader.ReadByte(),
                    Reserved = reader.ReadByte(),
                    Planes = reader.ReadUInt16(),
                    BitCount = reader.ReadUInt16(),
                    BytesInRes = reader.ReadUInt32(),
                    ImageOffset = reader.ReadUInt32()
                };
            }

            // ---- Decode each entry ----
            var textures = new Texture2D[count];
            for (int i = 0; i < count; i++)
            {
                ICODirEntry e = entries[i];

                // Seek to image data
                reader.BaseStream.Seek(e.ImageOffset, SeekOrigin.Begin);
                byte[] imageData = reader.ReadBytes((int)e.BytesInRes);

                Texture2D tex;
                if (IsPNG(imageData))
                    tex = DecodePNGEntry(imageData, filterMode, wrapMode);
                else
                    tex = DecodeDIBEntry(imageData, e, filterMode, wrapMode);

                textures[i] = tex;
            }

            return textures;
        }

        /// <summary>
        /// Loads a .ico file from disk and returns all contained images as Texture2Ds.
        /// </summary>
        /// <param name="filePath">Full path to the .ico file.</param>
        /// <param name="filterMode">Filter mode applied to each resulting texture.</param>
        /// <param name="wrapMode">Wrap mode applied to each resulting texture.</param>
        /// <returns>An array of Texture2D objects, one per image in the ICO file.</returns>
        public static Texture2D[] ICOFileToTextures(
            string filePath,
            FilterMode filterMode = FilterMode.Bilinear,
            TextureWrapMode wrapMode = TextureWrapMode.Clamp)
        {
            if (string.IsNullOrEmpty(filePath))
                throw new ArgumentException("File path must not be null or empty.", nameof(filePath));
            if (!File.Exists(filePath))
                throw new FileNotFoundException("ICO file not found.", filePath);

            return ICOBytesToTextures(File.ReadAllBytes(filePath), filterMode, wrapMode);
        }

        /// <summary>
        /// Convenience overload: loads a .ico file and returns only the largest image entry.
        /// </summary>
        public static Texture2D ICOFileToLargestTexture(string filePath)
        {
            Texture2D[] all = ICOFileToTextures(filePath);
            Texture2D largest = all[0];
            foreach (var t in all)
                if (t.width * t.height > largest.width * largest.height)
                    largest = t;
            return largest;
        }

        /// <summary>
        /// Convenience overload: converts ICO bytes and returns only the largest image entry.
        /// </summary>
        public static Texture2D ICOBytesToLargestTexture(byte[] icoBytes)
        {
            Texture2D[] all = ICOBytesToTextures(icoBytes);
            Texture2D largest = all[0];
            foreach (var t in all)
                if (t.width * t.height > largest.width * largest.height)
                    largest = t;
            return largest;
        }

        #endregion

        #region Private Encoding

        /// <summary>
        /// Encodes a Texture2D into an ICO DIB block (BITMAPINFOHEADER + BGRA rows + AND mask).
        /// Rows are stored bottom-up as required by the BMP/ICO DIB format.
        /// </summary>
        private static byte[] EncodeDIB(Texture2D texture)
        {
            int w = texture.width;
            int h = texture.height;

            // GetPixels32 returns pixels left-to-right, bottom-to-top (Unity convention)
            Color32[] pixels = texture.GetPixels32();

            // XOR (colour) mask: 4 bytes per pixel (BGRA), bottom-up — already in correct order
            int xorStride = w * 4;
            int xorSize = xorStride * h;

            // AND mask: 1 bit per pixel, rows padded to 4-byte boundary, bottom-up
            int andStride = ((w + 31) / 32) * 4; // bytes per row, aligned to DWORD
            int andSize = andStride * h;

            using var ms = new MemoryStream(BMIH_SIZE + xorSize + andSize);
            using var writer = new BinaryWriter(ms);

            // ---- BITMAPINFOHEADER (40 bytes) ----
            writer.Write((uint)BMIH_SIZE); // biSize
            writer.Write((int)w);          // biWidth
            writer.Write((int)(h * 2));    // biHeight — doubled for ICO (XOR + AND stacked)
            writer.Write((ushort)1);       // biPlanes
            writer.Write((ushort)32);      // biBitCount
            writer.Write((uint)0);         // biCompression — BI_RGB
            writer.Write((uint)xorSize);   // biSizeImage
            writer.Write((int)0);          // biXPelsPerMeter
            writer.Write((int)0);          // biYPelsPerMeter
            writer.Write((uint)0);         // biClrUsed
            writer.Write((uint)0);         // biClrImportant

            // ---- XOR mask (BGRA, bottom-up) ----
            // Unity's GetPixels32 already returns bottom-up, so no row reversal needed.
            foreach (Color32 c in pixels)
            {
                writer.Write(c.b);
                writer.Write(c.g);
                writer.Write(c.r);
                writer.Write(c.a);
            }

            // ---- AND mask (1-bit alpha mask, bottom-up) ----
            // A pixel is transparent (1) when alpha == 0, opaque (0) otherwise.
            // Unity pixels are already bottom-up, so process rows in order.
            byte[] andMask = new byte[andSize];
            for (int row = 0; row < h; row++)
            {
                for (int col = 0; col < w; col++)
                {
                    Color32 p = pixels[row * w + col];
                    if (p.a == 0)
                    {
                        int byteIdx = row * andStride + col / 8;
                        int bitIdx = 7 - (col % 8); // MSB first
                        andMask[byteIdx] |= (byte)(1 << bitIdx);
                    }
                }
            }
            writer.Write(andMask);

            return ms.ToArray();
        }

        #endregion

        #region Private Decoding

        /// <summary>
        /// Decodes an uncompressed 32-bit DIB entry into a Texture2D.
        /// </summary>
        private static Texture2D DecodeDIBEntry(
            byte[] data,
            ICODirEntry entry,
            FilterMode filterMode,
            TextureWrapMode wrapMode)
        {
            using var reader = new BinaryReader(new MemoryStream(data));

            // BITMAPINFOHEADER
            uint biSize = reader.ReadUInt32();
            int biWidth = reader.ReadInt32();
            int biHeight = reader.ReadInt32(); // doubled in ICO format
            ushort biPlanes = reader.ReadUInt16();
            ushort biBitCount = reader.ReadUInt16();
            uint biCompression = reader.ReadUInt32();
            uint biSizeImage = reader.ReadUInt32();
            reader.BaseStream.Seek(16, SeekOrigin.Current); // skip remaining BMIH fields

            // Actual pixel height is biHeight / 2 (ICO doubles it to include AND mask)
            int w = biWidth;
            int h = Mathf.Abs(biHeight) / 2;

            // Fallback to directory entry dimensions if header reports 0
            if (w == 0) w = entry.Width == 0 ? 256 : entry.Width;
            if (h == 0) h = entry.Height == 0 ? 256 : entry.Height;

            // Skip any extra header bytes beyond the standard 40
            long extraHeaderBytes = biSize - BMIH_SIZE;
            if (extraHeaderBytes > 0)
                reader.BaseStream.Seek(extraHeaderBytes, SeekOrigin.Current);

            var tex = new Texture2D(w, h, TextureFormat.RGBA32, false);
            tex.filterMode = filterMode;
            tex.wrapMode = wrapMode;

            Color32[] pixels = new Color32[w * h];

            if (biBitCount == 32)
            {
                // 32-bit BGRA — rows are stored bottom-up in DIB, matching Unity's GetPixels32 order
                for (int i = 0; i < w * h; i++)
                {
                    byte b = reader.ReadByte();
                    byte g = reader.ReadByte();
                    byte r = reader.ReadByte();
                    byte a = reader.ReadByte();
                    pixels[i] = new Color32(r, g, b, a);
                }
            }
            else if (biBitCount == 24)
            {
                // 24-bit BGR — no alpha channel, rows padded to 4-byte boundary, bottom-up
                int rowPad = (4 - (w * 3) % 4) % 4;
                for (int row = 0; row < h; row++)
                {
                    for (int col = 0; col < w; col++)
                    {
                        byte b = reader.ReadByte();
                        byte g = reader.ReadByte();
                        byte r = reader.ReadByte();
                        pixels[row * w + col] = new Color32(r, g, b, 255);
                    }
                    reader.BaseStream.Seek(rowPad, SeekOrigin.Current);
                }

                // Read AND mask and apply as alpha
                int andStride = ((w + 31) / 32) * 4;
                for (int row = 0; row < h; row++)
                {
                    for (int col = 0; col < w; col++)
                    {
                        int byteIdx = row * andStride + col / 8;
                        // AND mask was read separately — re-seek to mask start isn't practical here
                        // so we leave alpha as 255 for 24-bit entries (mask rarely used meaningfully)
                        _ = byteIdx;
                    }
                }
            }
            else
            {
                throw new NotSupportedException(
                    $"ICO DIB entry with {biBitCount} bits per pixel is not supported. " +
                    "Only 24-bit and 32-bit entries are supported.");
            }

            tex.SetPixels32(pixels);
            tex.Apply();
            return tex;
        }

        /// <summary>
        /// Decodes a PNG-embedded ICO entry using Unity's built-in PNG loader.
        /// </summary>
        private static Texture2D DecodePNGEntry(
            byte[] pngData,
            FilterMode filterMode,
            TextureWrapMode wrapMode)
        {
            var tex = new Texture2D(2, 2, TextureFormat.RGBA32, false);
            tex.filterMode = filterMode;
            tex.wrapMode = wrapMode;

            if (!ImageConversion.LoadImage(tex, pngData, false))
                throw new InvalidDataException("Failed to decode PNG-embedded ICO entry.");

            return tex;
        }

        /// <summary>
        /// Returns true if the given bytes begin with the PNG file signature.
        /// </summary>
        private static bool IsPNG(byte[] data)
        {
            if (data.Length < PNG_MAGIC.Length) return false;
            for (int i = 0; i < PNG_MAGIC.Length; i++)
                if (data[i] != PNG_MAGIC[i]) return false;
            return true;
        }

        #endregion

        #region Internal Types

        private struct ICODirEntry
        {
            public byte Width;
            public byte Height;
            public byte ColorCount;
            public byte Reserved;
            public ushort Planes;
            public ushort BitCount;
            public uint BytesInRes;
            public uint ImageOffset;
        }

        #endregion
    }
